// Generated by the platform for one session and mounted read-only. Streams tool activity to the platform
// and enforces the harness policy before a tool runs. Agents cannot modify or disable it.
const ENDPOINT = __ENDPOINT__;
const KEY = __KEY__;
const POLICY = __POLICY__;
const WATCHED = new Set([
  "session.status",
  "session.idle",
  "session.error",
  "session.compacted",
  "file.edited",
  "permission.asked",
  "permission.replied",
  "todo.updated",
]);
const started = new Map();
const denyCommands = POLICY.deny_commands.map((pattern) => [pattern, new RegExp(pattern)]);
const denyPaths = POLICY.deny_paths.map((pattern) => [pattern, new RegExp(pattern)]);

function send(kind, data) {
  fetch(ENDPOINT, {
    method: "POST",
    headers: { "Content-Type": "application/json", "X-Platform-Key": KEY },
    body: JSON.stringify({ kind, at: Date.now(), ...data }),
    signal: AbortSignal.timeout(5000),
  }).catch(() => {});
}

function summarize(value) {
  const text = JSON.stringify(value ?? {});
  return text.length > 1000 ? text.slice(0, 1000) + "…" : text;
}

function violation(tool, args) {
  if (tool === "bash") {
    const command = String(args?.command ?? "");
    for (const [pattern, regex] of denyCommands) if (regex.test(command)) return `command matches ${pattern}`;
  }
  const path = String(args?.filePath ?? args?.path ?? "");
  if (path) for (const [pattern, regex] of denyPaths) if (regex.test(path)) return `path matches ${pattern}`;
  return null;
}

export const PlatformMonitor = async () => ({
  "tool.execute.before": async (input, output) => {
    started.set(input.callID, Date.now());
    const reason = violation(input.tool, output.args);
    const base = { tool: input.tool, call_id: input.callID, conversation: input.sessionID, args: summarize(output.args) };
    if (reason) {
      send("tool.blocked", { ...base, reason });
      throw new Error(`Blocked by platform policy: ${reason}`);
    }
    send("tool.start", base);
  },
  "tool.execute.after": async (input, output) => {
    const begin = started.get(input.callID);
    started.delete(input.callID);
    send("tool.end", {
      tool: input.tool,
      call_id: input.callID,
      conversation: input.sessionID,
      duration_ms: begin ? Date.now() - begin : null,
      title: String(output?.title ?? "").slice(0, 300),
      output_bytes: String(output?.output ?? "").length,
    });
  },
  event: async ({ event }) => {
    if (!WATCHED.has(event.type)) return;
    send("event", { event: event.type, details: summarize(event.properties) });
  },
});
